import json, subprocess, collections, statistics, os
T=['BornholmBitextMining','NorwegianCourtsBitextMining','AngryTweetsClassification','DanishPoliticalCommentsClassification','DalajClassification','DKHateClassification','LccSentimentClassification','MassiveIntentClassification','MassiveScenarioClassification','NordicLangClassification','NoRecClassification','NorwegianParliamentClassification','ScalaClassification','SwedishSentimentClassification','SweRecClassification','DanFeverRetrieval','NorQuadRetrieval','SNLRetrieval','SwednRetrieval','SweFaqRetrieval','TV2Nordretrieval','TwitterHjerneRetrieval','SNLHierarchicalClusteringS2S','SNLHierarchicalClusteringP2P','SwednClusteringP2P','SwednClusteringS2S','VGHierarchicalClusteringS2S','VGHierarchicalClusteringP2P']
Tset=set(T)
allpaths=[]
for line in open('/tmp/aug_paths.txt'):
 p=line.strip();parts=p.split('/')
 if len(parts)>=4 and parts[-1].endswith('.json') and parts[-1][:-5] in Tset: allpaths.append((parts[1],parts[-1][:-5],p))
# read all blobs
D={}
for m,t,p in allpaths:
 try: D[p]=json.loads(subprocess.check_output(['git','-C','/tmp/results_aug','show','HEAD:'+p]))
 except Exception as e: print('error',p,e)
by=collections.defaultdict(lambda:collections.defaultdict(list))
for m,t,p in allpaths:
 d=D[p]
 def extract(d):
  # return list score values from test split, old or new MTEB format
  if 'scores' in d:
   x=d['scores'].get('test')
   if isinstance(x,list): return [z.get('main_score') for z in x if isinstance(z,dict) and isinstance(z.get('main_score'),(int,float))]
   if isinstance(x,dict) and isinstance(x.get('main_score'),(int,float)): return [x['main_score']]
   return []
  x=d.get('test')
  if isinstance(x,dict):
   if isinstance(x.get('main_score'),(int,float)): return [x['main_score']]
   # multilingual old format: each language/subset dict
   return [v.get('main_score') for v in x.values() if isinstance(v,dict) and isinstance(v.get('main_score'),(int,float))]
  if isinstance(x,list): return [z.get('main_score') for z in x if isinstance(z,dict) and isinstance(z.get('main_score'),(int,float))]
  return []
 vals=extract(d)
 if vals: by[m][t].append((p.split('/')[-2],len(vals),sum(vals)/len(vals),vals))
# models with file paths all 28
fileby=collections.defaultdict(set)
for m,t,p in allpaths:fileby[m].add(t)
for m in sorted(m for m in fileby if len(fileby[m])==28):
 missing=[t for t in T if not by[m].get(t)]
 print('\nMODEL',m,'valid',len(by[m]),'missing',missing)
 # Use first valid path; if multiple, show means
 vals=[]
 for t in T:
  a=by[m].get(t,[])
  if a:
   vals.append(a[0][2]);
   if len(a)>1: print('DUP',t,[(x[0],x[1],x[2]) for x in a])
  else: print('MISS',t)
 if len(vals)==28: print('MEAN',statistics.mean(vals), 'x100',statistics.mean(vals)*100)
